// Готовим Basic Auth и временной диапазон для запроса к Traccar
const username = process.env.TRACCAR_USERNAME || '';
const password = process.env.TRACCAR_PASSWORD || '';
const auth = Buffer.from(`${username}:${password}`).toString('base64');

const now = new Date();
// Смотрим назад на 48 часов — подхватит поездки если n8n был недоступен
const from = new Date(now.getTime() - 48 * 60 * 60 * 1000).toISOString();
const to = now.toISOString();

return [{
  json: {
    auth_header: `Basic ${auth}`,
    device_id: process.env.TRACCAR_DEVICE_ID || '',
    traccar_url: (process.env.TRACCAR_URL || '').replace(/\/$/, ''),
    from_time: from,
    to_time: to
  }
}];

// Фильтруем поездки, которые уже отправляли в Telegram
// Используем n8n Workflow Static Data (хранится в SQLite внутри n8n)
const responseData = $input.first().json;
const trips = Array.isArray(responseData) ? responseData : [];

if (trips.length === 0) {
  return [];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.sentTripKeys) {
  staticData.sentTripKeys = [];
}

const sentKeys = new Set(staticData.sentTripKeys);

// Уникальный ключ: deviceId + время начала поездки
const newTrips = trips.filter(trip => {
  const key = `${trip.deviceId}_${trip.startTime}`;
  return !sentKeys.has(key);
});

if (newTrips.length === 0) {
  return [];
}

// Помечаем как отправленные
newTrips.forEach(trip => {
  sentKeys.add(`${trip.deviceId}_${trip.startTime}`);
});

// Оставляем последние 500 ключей
staticData.sentTripKeys = [...sentKeys].slice(-500);

return newTrips.map(trip => ({ json: trip }));

const trip = $input.item.json;

// Расстояние: Traccar возвращает в метрах
const distanceKm = trip.distance / 1000;
const distanceStr = distanceKm.toFixed(1);

// Длительность: в миллисекундах
const durationMs = trip.duration || 0;
const hours = Math.floor(durationMs / 3600000);
const mins = Math.floor((durationMs % 3600000) / 60000);
const durationStr = hours > 0 ? `${hours}ч ${mins}мин` : `${mins}мин`;

// Скорость: Traccar хранит в узлах (knots) → км/ч (* 1.852)
const avgSpeedKmh = Math.round((trip.averageSpeed || 0) * 1.852);
const maxSpeedKmh = Math.round((trip.maxSpeed || 0) * 1.852);
const speedStr = maxSpeedKmh > 0
  ? `${avgSpeedKmh} / ${maxSpeedKmh} км/ч (сред / макс)`
  : `${avgSpeedKmh} км/ч (средняя)`;

// Топливо: берём от OBD если есть, иначе считаем по расстоянию
const actualFuel = (trip.spentFuel != null && trip.spentFuel > 0)
  ? parseFloat(trip.spentFuel)
  : null;
const fuelL100km = parseFloat(process.env.FUEL_L100KM || '7.0');
const fuel = actualFuel !== null ? actualFuel : (distanceKm * fuelL100km / 100);
const fuelLabel = actualFuel !== null ? '' : ' (~расчёт)';
const fuelStr = `${fuel.toFixed(2)} л${fuelLabel}`;

// Стоимость
const dieselPrice = parseFloat(process.env.DIESEL_PRICE_PLN || '6.50');
const cost = (fuel * dieselPrice).toFixed(2);

// Форматирование времени (варшавский TZ)
const fmt = (isoStr) => new Date(isoStr).toLocaleString('ru-RU', {
  timeZone: 'Europe/Warsaw',
  day: '2-digit',
  month: '2-digit',
  hour: '2-digit',
  minute: '2-digit'
});

const lines = [
  '🚗 *Поездка завершена*',
  '',
  `📍 ${trip.startAddress || '—'} → ${trip.endAddress || '—'}`,
  '',
  `📏 Расстояние: *${distanceStr} км*`,
  `⏱ Время в пути: *${durationStr}*`,
  `⚡ Скорость: ${speedStr}`,
  `⛽ Топливо: *${fuelStr}*`,
  `💰 Стоимость: *${cost} PLN* (${dieselPrice} PLN/л)`,
  '',
  `🕐 ${fmt(trip.startTime)} → ${fmt(trip.endTime)}`,
];

return [{
  json: {
    chat_id: process.env.TELEGRAM_CHAT_ID,
    bot_token: process.env.TELEGRAM_BOT_TOKEN,
    text: lines.join('\n'),
    parse_mode: 'Markdown'
  }
}];
